if(t=='i'){const it=item(k);h=(IMG[it.id]?`<img src="${IMG[it.id]}" style="display:block;width:100%;max-height:260px;object-fit:contain;border-radius:12px;border:1px solid var(--bd);background:#fff;cursor:zoom-in;margin-bottom:10px" onclick="imgZoom(${it.id})">`:'')+`<h2>${it.n}</h2><div class="m">${it.code} | ${cat(it.cat).n} | متاح ${it.qty} | بيع ${m(it.price)} | شراء ${sec(m(it.cost))}</div><h3>المبيعات</h3>`+T(['التاريخ','العميل','الكمية','السعر','البائع'],D.sales.flatMap(s=>s.lines.filter(l=>l.iid==k).map(l=>R('',[s.date,s.cust,l.q,m(l.p),s.user]))))+'<h3>الشراء</h3>'+T(['التاريخ','المورد','الكمية','السعر','المستخدم'],D.buys.filter(b=>b.iid==k).map(b=>R('',[b.d,sup(b.sid).n,b.q,sec(m(b.c)),b.u])))}
