function editCust(id){const s=D.sales.find(x=>x.id==id);if(!canEdit(s.ts)){askAdminPw(()=>editCust(id));return}form('تعديل بيانات العميل',[{k:'c',l:'الاسم',v:s.cust},{k:'p',l:'الهاتف',v:s.phone}],v=>{LOG('تعديل بيانات عميل فاتورة #'+s.no);s.cust=v.c||s.cust;s.phone=v.p;toast('تم التعديل')})}
function cancelSale(id){askAdmin(()=>{if(!confirm('إلغاء الفاتورة وإرجاع الكميات للمخزون؟'))return;const s=D.sales.find(x=>x.id==id);s.lines.forEach(l=>{const q=l.q-(l.r||0);if(q>0)stIn(item(l.iid),q,l.c)});serFree(s);carryUndo(s);const _re=new RegExp('#'+s.no+'(?!\\d)');D.cash=D.cash.filter(e=>!_re.test(e.note||''));D.rets=D.rets.filter(r=>r.no!=s.no);LOG('إلغاء فاتورة #'+s.no+' - '+s.cust);D.sales=D.sales.filter(x=>x.id!=id);closeF();toast('تم إلغاء الفاتورة');go(tab)})}
