function form(title,fields,ok,nr){$('box').innerHTML=`<h2>${title}</h2>`+fields.map(f=>`<label>${f.l}</label>`+(f.o?`<select id="f_${f.k}">${f.o.map(o=>`<option value="${o[0]}" ${o[0]==f.v?'selected':''}>${o[1]}</option>`).join('')}</select>`:`<input id="f_${f.k}" type="${f.t=='date'?'text':(f.t||'text')}" ${f.t=='date'?'placeholder="DD/MM/YYYY"':''} value="${f.v==null?'':f.v}">`)).join('')+'<div class="row" style="margin-top:16px"><button class="btn g" onclick="closeF()">إلغاء</button><button class="btn" id="okb">حفظ</button></div>';$('ov').className='on';
$('okb').onclick=()=>{const v={};for(const f of fields){const x=$('f_'+f.k).value;if(f.t=='date'){v[f.k]=parseD(x);if(!v[f.k]){toast('تاريخ غير صحيح، اكتبه بالشكل 25/12/2026');return}}else v[f.k]=f.t=='number'?parseFloat(x)||0:x}if(ok(v)!==false){closeF();if(!nr)go(tab)}}}
