let TRS=null;
const isAr=c=>!!c&&/[\u0621-\u064A\u0671-\u06D3]/.test(c);
function trText(t){if(!D||!D.set||D.set.lang!='en')return t;if(!TRS)TRS=TRD.slice().sort((a,b)=>b[0].length-a[0].length);let r=t;
for(const [a,e] of TRS){if(!r.includes(a))continue;const ba=isAr(a[0]),bz=isAr(a[a.length-1]);let o='',i=0,j;while((j=r.indexOf(a,i))>=0){const pre=r[j-1],post=r[j+a.length];if((ba&&isAr(pre))||(bz&&isAr(post)))o+=r.slice(i,j+a.length);else o+=r.slice(i,j)+e;i=j+a.length}r=o+r.slice(i)}return r}
