function subv(){const S=D.sub||(D.sub={av:0,ow:0,log:[]}),drawn=S.log.filter(x=>x.t=='draw').reduce((a,x)=>a+x.a,0);
return `<div class="row"><h2>الخزنة الفرعية</h2><div>${PB('الخزنة الفرعية',0)} <button class="btn s" onclick="subOp('cap')">+ إيداع تمويل</button> <button class="btn g s" onclick="subOp('draw')">⬇ سحب للرئيسية</button> <button class="btn g s" onclick="subOp('repay')">⬆ سداد للفرعية</button> <button class="btn g s" onclick="subOp('exp')">− مصروف من الفرعية</button></div></div><div class="m" style="margin-bottom:8px">فلوس خارجية (مش فلوس المعرض) بتلجأ لها وقت الحاجة. اللي بتسحبه منها بيزيد في "المستحق للفرعية" لحد ما تسدده، وبيدخل في معادلة الاستثمار كالتزام.</div><div class="grid"><div class="k"><span>المتاح في الفرعية</span><b>${m(S.av)}</b></div><div class="k"><span>مستحق للفرعية (عليك)</span><b style="color:var(--bad)">${m(S.ow)}</b></div><div class="k"><span>إجمالي اللي اتسحب</span><b>${m(drawn)}</b></div></div>`
+LB('حركات الفرعية',T(['التاريخ','الوقت','النوع','البيان','الشخص','المسؤول','المبلغ','المتاح بعدها','المستحق بعدها'],S.log.slice().reverse().map(x=>R(x.t=='draw'||x.t=='exp'?'warn':'ok',[x.d,tm(x.ts)||'-',SUBL[x.t],x.note||'-',x.person||'-',x.u,m(x.a),m(x.av),m(x.ow)]))))}
function subOp(t){const S=D.sub||(D.sub={av:0,ow:0,log:[]});form(({cap:'إيداع تمويل في الخزنة الفرعية',draw:'سحب من الفرعية للخزنة الرئيسية',repay:'سداد للفرعية من الخزنة الرئيسية',exp:'مصروف من الخزنة الفرعية'})[t],[{k:'a',l:'المبلغ',t:'number',v:0},{k:'note',l:'البيان'},{k:'person',l:'اسم صاحب الفلوس / الشخص'},{k:'who',l:'اسم من نفّذ الحركة',v:D.who||''}],v=>{
if(v.a<=0||!v.who.trim()){toast('اكتب المبلغ واسم المسؤول عن الحركة');return false}
if((t=='draw'||t=='exp')&&v.a>S.av+0.001){toast('المتاح في الفرعية '+m(S.av)+' بس');return false}if(t=='repay'&&v.a>S.ow+0.001){toast('المستحق للفرعية '+m(S.ow)+' بس');return false}
D.who=v.who;const nt=v.note?' - '+v.note:'';
if(t=='cap')S.av+=v.a;else if(t=='draw'){S.av-=v.a;S.ow+=v.a;D.cash.push({d:today(),t:'in',a:v.a,note:'سحب من الخزنة الفرعية'+nt,person:v.person||'الخزنة الفرعية',u:v.who,man:1,sub:1})}else if(t=='repay'){S.ow-=v.a;S.av+=v.a;D.cash.push({d:today(),t:'out',a:v.a,note:'تسديد للخزنة الفرعية'+nt,person:v.person||'الخزنة الفرعية',u:v.who,man:1,sub:1})}else{S.av-=v.a;S.ow+=v.a}
S.log.push({d:today(),ts:Date.now(),t,a:v.a,note:v.note||'',person:v.person||'',u:v.who,av:S.av,ow:S.ow});LOG('الخزنة الفرعية - '+SUBL[t]+' '+Math.round(v.a)+' (بواسطة '+v.who+')')})}
const tgOn=()=>!!(D.set.tgTok&&D.set.tgChat);
async function tgApi(method,body){const r=await fetch('https://api.telegram.org/bot'+D.set.tgTok+'/'+method,{method:'POST',body});const j=await r.json();if(!j.ok)throw new Error(j.description||'telegram error');return j}
async function tgSend(text){const fm=new FormData();fm.append('chat_id',D.set.tgChat);fm.append('text',text);return tgApi('sendMessage',fm)}
async function tgFileSend(name,bytes,caption,mime){const fm=new FormData();fm.append('chat_id',D.set.tgChat);if(caption)fm.append('caption',caption);fm.append('document',new Blob([bytes],{type:mime||'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),name);return tgApi('sendDocument',fm)}
async function dailyXlsx(){return mkXlsx([['العملاء',dataCust()],['الأقساط',dataInst()],['المنتجات',dataProd()],['المبيعات',dataSales()],['فواتير العملاء',dataInvLines()]])}
function daySummaryText(d){const n=dayNums(d),sl=D.sales.filter(s=>s.date==d&&!s.legacy),pi=D.pinv.filter(p=>p.d==d),rt=D.rets.filter(r=>r.d==d),c=D.closed[d],late=D.sales.filter(s=>stOf(s)=='late'),S=D.sub||{av:0,ow:0};
const L=['🏬 '+D.shop,(c?'🔒 إقفال يوم ':'📅 ملخص يوم ')+fd(d)+(c?' - بواسطة '+c.by+(c.ts?' الساعة '+tm(c.ts):''):' (اليوم لسه مش مقفول)'),'━━━━━━━━━━━━',
'🧾 المبيعات: '+sl.length+' فاتورة بإجمالي '+m(sl.reduce((a,s)=>a+stv(s),0))+' (نقدي '+sl.filter(s=>s.type=='cash').length+' | تقسيط '+sl.filter(s=>s.type=='inst').length+')',
'💵 داخل الخزنة: '+m(n.i),'💸 خارج الخزنة: '+m(n.o),'📈 صافي اليوم: '+m(n.i-n.o),
...dayCats(d).filter(r=>r[1]||r[2]).map(r=>' • '+r[0]+': داخل '+m(r[1])+' / خارج '+m(r[2])),
'↩️ المرتجعات: '+rt.length+' عملية','🚚 فواتير الشراء: '+pi.length+' بإجمالي '+m(pi.reduce((a,p)=>a+p.total,0)),'━━━━━━━━━━━━',
'🏦 رصيد بداية اليوم: '+m(n.op),'🏦 رصيد نهاية اليوم (الدفتري): '+m(n.cl),
...(c&&c.actual!=null?['✋ الفعلي بالعد: '+m(c.actual),'⚖️ الفرق: '+(c.diff>0?'+':'')+m(c.diff)+(Math.abs(c.diff)>0.5?'  ⚠️':'  ✅')]:[]),'━━━━━━━━━━━━',
'👥 مستحق عند العملاء: '+m(D.sales.reduce((a,s)=>a+Math.max(0,rem(s)),0)),'⚠️ أقساط متأخرة: '+late.length+' فاتورة بمبلغ '+m(late.reduce((a,s)=>a+Math.max(0,rem(s)),0)),'🚚 مستحق للموردين: '+m(D.sup.reduce((a,s)=>a+s.owed,0)),'🏦 الخزنة الفرعية: متاح '+m(S.av)+' | مستحق لها '+m(S.ow)];
return L.join('\n')}
async function tgDayReport(d,quiet){if(!tgOn()){if(!quiet)toast('اكتب مفتاح البوت ومعرّف الشات في الإعدادات (تيليجرام)');return false}
try{if(!quiet)toast('جاري الإرسال لتيليجرام...');await tgSend(daySummaryText(d));if(D.set.tgFile!==0){const bytes=await dailyXlsx();await tgFileSend('بيانات-'+dmy()+'.xlsx',bytes,'ملف البيانات اليومي - '+fd(d))}
if(D.set.tgMob!==0||D.set.tgSnap!==0){if(!D.set.mobPw){if(!quiet)toast('اكتب كلمة سر الملفات المشفّرة من الإعدادات ← 7-د عشان ملفات الموبايل تتبعت')}else{if(D.set.tgMob!==0){const f=await buildMobFile();if(f)await tgFileSend('acc-'+dmy()+'.accdata',new TextEncoder().encode(f),'ملف بيانات الموبايل (مشفّر) - '+fd(d)+' — دوس عليه وافتحه بتطبيق الموبايل','application/octet-stream')}
if(D.set.tgSnap!==0){const h=await buildSnapshot();if(h)await tgFileSend('snapshot-'+dmy()+'.html',new TextEncoder().encode(h),'نسخة اللابتوب (مشفّرة) - '+fd(d)+' — افتحها بالمتصفح واكتب كلمة السر','text/html')}}}if(d==today())D.set.tgDay=d;LOG('إرسال ملخص يوم '+fd(d)+' لتيليجرام');save();if(!quiet)toast('تم إرسال ملخص اليوم'+(D.set.tgFile!==0?' وملف البيانات':'')+' لتيليجرام ✅');return true}catch(e){toast('تعذر الإرسال لتيليجرام: '+(e.message||e)+' (الإرسال بيشتغل في البرنامج المثبت)');return false}}
function tgManual(){tgDayReport(CD)}
async function tgTest(){if(!tgOn()){toast('اكتب مفتاح البوت ومعرّف الشات الأول');return}try{await tgSend('✅ رسالة تجريبية من '+D.shop+' — الربط شغال.');toast('اتبعتت رسالة تجريبية لتيليجرام ✅')}catch(e){toast('تعذر الإرسال: '+(e.message||e)+' (الإرسال بيشتغل في البرنامج المثبت)')}}

