const LOGIGN=new Set(['log','n','no','pno','qno','rno','read','who','seller']),SETIGN=/^(m\d+|lastBk|tgDay|bkName)$/,SECRETK=new Set(['pw','tgTok','tgChat','gCid','gClientId']);
