function getAt(p){let c=D;for(const k of p){if(c==null)return undefined;if(k&&typeof k=='object')c=Array.isArray(c)?c.find(x=>x&&x.id==k.id):undefined;else c=c[k]}return c}
function undoCheck(o){const par=getAt(o.p.slice(0,-1)),key=o.p[o.p.length-1];
if(o.o=='set')return jeq(getAt(o.p),o.a);if(o.o=='add')return !!par&&typeof par=='object'&&key in par&&jeq(par[key],o.v);if(o.o=='del')return !!par&&typeof par=='object'&&!(key in par);
const ar=getAt(o.p);if(!Array.isArray(ar))return false;if(o.o=='addid')return ar.some(x=>x.id==o.id&&jeq(x,o.v));if(o.o=='rmid')return !ar.some(x=>x.id==o.id);if(o.o=='spl')return jeq(ar.slice(o.i,o.i+o.n.length),o.n);return false}
