function stIn(it,q,c){if(!it||it===LEG||!(q>0)){if(it&&it!==LEG&&q)it.qty+=q;return}c=(c==null||isNaN(c))?it.cost:c;const base=Math.max(it.qty,0);if(base+q>0)it.cost=Math.round((base*it.cost+q*c)/(base+q)*100)/100;it.qty+=q}
function stOut(it,q,c){if(!it||it===LEG){return}c=(c==null||isNaN(c))?it.cost:c;const tq=it.qty-q;if(tq>0&&it.qty>0)it.cost=Math.max(0,Math.round((it.qty*it.cost-q*c)/tq*100)/100);it.qty=tq}
function costFromBuys(it){const lots=D.buys.filter(b=>b.iid==it.id).sort((a,b)=>(b.ts||0)-(a.ts||0)||(b.d>a.d?1:b.d<a.d?-1:0));let need=it.qty,sum=0,got=0;for(const b of lots){if(need<=0)break;const t=Math.min(b.q,need);sum+=t*b.c;got+=t;need-=t}if(need>0){sum+=need*it.cost;got+=need}return got>0?Math.round(sum/got*100)/100:it.cost}
