function serSold(s){(s.lines||[]).forEach(l=>{if(!l.sn)return;const u=(D.sn||[]).find(x=>x.sn==l.sn);if(u){u.st='sold';u.sid=s.id;u.sd=s.date;u.cust=s.cust;serRecost(item(u.iid))}})}
