function serBuyCheck(plan){const seen=new Set();for(const x of plan){const ser=x.it?isSer(x.it):isSerCat(cat(x.nw.cat).n);if(!ser)continue;const tk=snTok(x.sns),nm=x.it?x.it.n:x.nw.n;if(tk.length!=x.q)return 'الصنف '+nm+': لازم تدخل '+x.q+' سيريال/IMEI (دخلت '+tk.length+') — اضغط خانة السيريالات';for(const t of tk){if(seen.has(t))return 'السيريال '+t+' مكرر في الفاتورة';seen.add(t);if((D.sn||[]).some(u=>u.sn==t))return 'السيريال '+t+' موجود قبل كده في النظام'}}return ''}
