let CSL=[],CIGN='',CBXH='';
function custIdx(){const ix={};D.sales.forEach(s=>{const k=s.cust;if(!k)return;const c=ix[k]||(ix[k]={n:k,p:'',last:'',cnt:0,owe:0,inv:[]});c.cnt++;if(s.phone)c.p=s.phone;if(!c.last||s.date>c.last)c.last=s.date;const r=rem(s);if(r>0.5&&!(S&&S.edit&&s.id==S.edit)){c.owe+=r;c.inv.push({id:s.id,no:s.no,amt:Math.round(r*100)/100,date:s.date,type:s.type})}});Object.keys(D.cm||{}).forEach(k=>{if(!ix[k])ix[k]={n:k,p:(D.cm[k].p2||''),last:'',cnt:0,owe:0,inv:[]}});return ix}
function custSim(q){const nq=norm(q);if(nq.length<2)return[];const tk=nq.split(' ').filter(x=>x.length>1);return Object.values(custIdx()).map(c=>{const nn=norm(c.n),ex=nn==nq,inc=nn.includes(nq)||nq.includes(nn),ov=tk.length?tk.filter(t=>nn.includes(t)).length/tk.length:0;return{c,ex,sc:ex?3:inc?2:ov>=0.6?1:0}}).filter(x=>x.sc).sort((a,b)=>b.sc-a.sc||b.c.cnt-a.c.cnt).slice(0,6)}
function custSug(){const b=$('csug');if(!b)return;const q=(S.cust||'').trim();let h='';const nq=norm(q),carried=(S.carry||[]).length;
const chips=(S.carry||[]).map((c,i)=>`<span class="chx" style="margin:2px">رصيد سابق #${c.no}: ${m(c.amt)}${S.edit?'':` <b onclick="carryDrop(${i})" style="cursor:pointer">✕</b>`}</span>`).join('');
if(!S.edit&&q.length>=2){const l=custSim(q),ex=l.find(x=>x.ex);CSL=l.map(x=>x.c.n);
if(l.length&&CIGN!=nq)h+=`<div class="k" style="margin:6px 0;border-right:4px solid var(--warn)"><b>${ex?'العميل موجود':'أسماء مشابهة'}</b> <span class="m">اختار الاسم أو اضغط تجاهل لو ده عميل جديد مختلف</span>${l.map((x,i)=>`<button type="button" class="dmi" onclick="custPick(${i})">${x.ex?'🟢':'🟡'} <span><b>${x.c.n}</b>${x.c.p?' — '+x.c.p:''}${x.c.last?' | آخر شراء '+fd(x.c.last):''}${x.c.owe>0.5?' | <b style="color:var(--bad)">عليه متبقي '+m(x.c.owe)+'</b>':''}</span></button>`).join('')}<button type="button" class="btn g s" style="margin-top:6px" onclick="CIGN=norm(S.cust);custSug()">تجاهل — عميل جديد مختلف</button></div>`;
if(ex&&ex.c.owe>0.5&&!carried&&CBXH!=nq)h+=`<div class="k" style="margin:6px 0;border-right:4px solid var(--bad)"><b>⚠ على العميل متبقي قديم ${m(ex.c.owe)}</b><div class="m">${ex.c.inv.map(x=>'فاتورة #'+x.no+' ('+(x.type=='inst'?'تقسيط':'نقدي')+'): '+m(x.amt)).join(' | ')}</div><div class="row" style="justify-content:flex-start;gap:8px;margin-top:8px"><button type="button" class="btn s" onclick="carryAdd()">➕ إضافة المتبقي القديم للفاتورة الجديدة</button><button type="button" class="btn g s" onclick="CBXH=norm(S.cust);custSug()">لا، سيبه</button></div><div class="m" style="margin-top:6px">لو أضفته بيدخل في إجمالي الفاتورة (من غير فايدة جديدة عليه)، والفاتورة القديمة بتتقفل بالترحيل.</div></div>`}
b.innerHTML=h+(chips?'<div style="margin:6px 0">'+chips+'</div>':'')}
function custPick(i){const n=CSL[i];if(n==null)return;S.cust=n;if($('cname'))$('cname').value=n;const c=custIdx()[n];if(c&&c.p&&!(S.phone||'').trim()){S.phone=c.p;if($('cphone'))$('cphone').value=c.p}const ct=cmGet(n).saleType;if(ct&&!S.lines.length){S.saleType=ct;if($('csaletype'))$('csaletype').value=ct}CIGN=norm(n);custSug()}
function carryAdd(){const c=custIdx()[(S.cust||'').trim()];S.carry=c?c.inv.map(x=>({sid:x.id,no:x.no,amt:x.amt})):[];refresh();custSug();toast('اتضاف الرصيد القديم للفاتورة')}
function carryDrop(i){(S.carry||[]).splice(i,1);refresh();custSug()}
function carryApply(s){(s.lines||[]).filter(l=>l.carry).forEach(l=>{const o=D.sales.find(x=>x.id==l.carry);if(!o)return;o.paid=Math.min(o.tot,o.paid+l.p);(o.pays=o.pays||[]).push({d:today(),ts:Date.now(),a:l.p,u:U.n,note:'ترحيل لفاتورة #'+s.no,tr:s.id});(o.xfer=o.xfer||[]).push(s.id)})}
function carryUndo(s){(s.lines||[]).filter(l=>l.carry).forEach(l=>{const o=D.sales.find(x=>x.id==l.carry);if(!o)return;o.paid=Math.max(0,o.paid-l.p);o.pays=(o.pays||[]).filter(p=>p.tr!=s.id);o.xfer=(o.xfer||[]).filter(i=>i!=s.id)})}
HELP.splice(HELP.findIndex(x=>x.t.startsWith('فاتورة بيع نقدي'))+1,0,{i:'👤',t:'اسم العميل التلقائي والرصيد القديم في الفاتورة',k:'عميل اسم تلقائي متشابه رصيد قديم متبقي إضافة',f:()=>'<ol><li>اكتب اسم العميل في الفاتورة: بتظهر <b>الأسماء المتشابهة</b> (🟢 موجود، 🟡 شبيه) ومعاها رقمه وآخر شراء واللي عليه.</li><li>اضغط على الاسم الصح: الاسم والتليفون بيتملوا لوحدهم. لو ده عميل جديد مختلف اضغط <b>تجاهل — عميل جديد مختلف</b>.</li><li>لو العميل عليه <b>متبقي قديم</b> بيظهر مربع أحمر بالمبلغ وفواتيره، وفيه زرار <b>➕ إضافة المتبقي القديم للفاتورة الجديدة</b> (بيظهر بس لو فعلاً عليه متبقي) وزرار <b>لا، سيبه</b>.</li><li>لو أضفته: بيدخل في إجمالي الفاتورة كسطر "رصيد سابق - فاتورة #..." <b>من غير فايدة جديدة عليه</b> (الفايدة على الأصناف الجديدة بس)، وبتقدر تشيله بـ✕ قبل الحفظ.</li><li>بعد الحفظ الفاتورة القديمة بتتقفل بـ"ترحيل" (من غير حركة خزنة)، والرصيد القديم مابيتعدّش في المبيعات والأرباح تاني. لو ألغيت الفاتورة الجديدة الرصيد بيرجع على القديمة.</li></ol>'});
