tb.querySelectorAll('tr.vgh').forEach(x=>x.remove());const rows=[...tb.rows].filter(r=>!r.querySelector('td.empty'));rows.sort((a,b)=>a.dataset.o-b.dataset.o);hc.forEach(h=>{delete h.dataset.sort});
