/* ===== صور الأصناف + نقاط الاسترجاع (IndexedDB) ===== */
var IMG={},SNPT=0,SNPR='',ITIMG=null,ITCUR='';
function idbo(){return new Promise((res,rej)=>{try{const r=indexedDB.open('acc_ext',1);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('imgs'))d.createObjectStore('imgs');if(!d.objectStoreNames.contains('snaps'))d.createObjectStore('snaps',{keyPath:'id'})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}catch(e){rej(e)}})}
function idbX(st,mode,fn){return idbo().then(db=>new Promise((res,rej)=>{const tx=db.transaction(st,mode),q=fn(tx.objectStore(st));tx.oncomplete=()=>res(q&&q.result);tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error)}))}
const idbPut=(st,v,k)=>idbX(st,'readwrite',os=>k===undefined?os.put(v):os.put(v,k));
const idbDel=(st,k)=>idbX(st,'readwrite',os=>os.delete(k));
const idbAll=st=>idbX(st,'readonly',os=>os.getAll());
function imgLoad(){idbo().then(db=>{const tx=db.transaction('imgs','readonly'),os=tx.objectStore('imgs'),k=os.getAllKeys(),v=os.getAll();tx.oncomplete=()=>{const m={};k.result.forEach((x,i)=>m[x]=v.result[i]);IMG=m;if(k.result.length&&typeof U!='undefined'&&U&&typeof tab!='undefined'&&tab){try{go(tab)}catch(e){}}}}).catch(()=>{})}
function imgSave(id,data){if(data){IMG[id]=data;idbPut('imgs',data,id).catch(()=>toast('تعذّر حفظ الصورة في المتصفح'))}else{delete IMG[id];idbDel('imgs',id).catch(()=>{})}}
function imgZoom(id){if(!IMG[id])return;$('box2').innerHTML=`<div style="text-align:center"><img src="${IMG[id]}" style="max-width:100%;max-height:75vh;object-fit:contain;border-radius:10px"></div><div class="row" style="margin-top:10px"><button type="button" class="btn g" onclick="closeF2()">إغلاق</button><button type="button" class="btn" onclick="closeF2();addItem(${id})">✏️ تغيير الصورة</button></div>`;$('ov2').className='on'}
function imgShow(){const p=$('itImgP');if(!p)return;const v=ITIMG===null?ITCUR:ITIMG;p.innerHTML=v?'<img src="'+v+'" style="width:84px;height:84px;object-fit:cover;border-radius:14px;border:1px solid var(--bd)">':'<div class="m" style="width:84px;height:84px;border:1px dashed var(--bd);border-radius:14px;display:grid;place-items:center">بدون صورة</div>'}
function imgPick(inp){const f=inp.files&&inp.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{const im=new Image();im.onload=()=>{const sc=Math.min(1,200/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*sc));c.height=Math.max(1,Math.round(im.height*sc));c.getContext('2d').drawImage(im,0,0,c.width,c.height);ITIMG=c.toDataURL('image/jpeg',0.75);imgShow()};im.onerror=()=>toast('الصورة دي مش مقروءة');im.src=rd.result};rd.readAsDataURL(f);inp.value=''}
function imgInit(id){ITIMG=null;ITCUR=id?(IMG[id]||''):'';const n=$('f_n');if(!n)return;const lab=n.previousElementSibling||n;lab.insertAdjacentHTML('beforebegin','<div style="display:flex;align-items:center;gap:12px;margin:6px 0 10px"><div id="itImgP"></div><div style="display:flex;flex-direction:column;gap:6px"><label class="btn g s" style="cursor:pointer;text-align:center">📷 صورة الصنف<input type="file" accept="image/*" hidden onchange="imgPick(this)"></label><button type="button" class="btn g s" onclick="ITIMG=\'\';imgShow()">حذف الصورة</button></div></div>');imgShow()}
function snapSave(reason,json){const id=Date.now();return idbPut('snaps',{id:id,t:new Date().toISOString(),reason:reason,json:json,n:json.length}).then(()=>idbAll('snaps')).then(a=>{a.sort((x,y)=>y.id-x.id);return Promise.all(a.slice(12).map(x=>idbDel('snaps',x.id)))}).catch(()=>{})}
function snapAuto(){const now=Date.now();if(now-SNPT<18e5)return;try{const old=localStorage.getItem(KEY);if(!old)return;SNPT=now;snapSave('تلقائية (قبل التعديلات)',old)}catch(e){}}
function snapNow(r){try{if(Date.now()-SNPT<20000&&SNPR==r)return;SNPT=Date.now();SNPR=r;snapSave(r,JSON.stringify(D))}catch(e){}}
