function snapList(){const el=$('snapl');if(!el)return;idbAll('snaps').then(a=>{a.sort((x,y)=>y.id-x.id);el.innerHTML=a.length?a.map(x=>{const d=new Date(x.id),dt=new Date(x.id-d.getTimezoneOffset()*60000).toISOString().slice(0,10);return `<div class="lri"><div><b>${dt} ${d.toTimeString().slice(0,5)}</b><div class="m">${x.reason} • ${Math.round(x.n/1024)} ك.ب</div></div><div style="display:flex;gap:6px"><button type="button" class="btn s" onclick="snapRestore(${x.id})">↩ استرجاع</button><button type="button" class="btn g s" onclick="snapDel(${x.id})">🗑</button></div></div>`}).join(''):'<div class="m">لسه مفيش نقاط استرجاع.</div>'}).catch(()=>{el.innerHTML='<div class="m">التخزين الداخلي للمتصفح مش متاح هنا، فنقاط الاسترجاع مش هتشتغل.</div>'})}
function snapDel(id){idbDel('snaps',id).then(snapList).catch(()=>{})}
async function snapRestore(id){if(!mgr()){toast('للمدير فقط');return}try{const x=(await idbAll('snaps')).find(y=>y.id==id);if(!x)return;if(!confirm('هترجّع كل البيانات لنقطة '+new Date(x.id).toLocaleString('ar-EG')+' ('+x.reason+')؟ هيتاخد نقطة للوضع الحالي الأول.'))return;await snapSave('قبل الاسترجاع',JSON.stringify(D));localStorage.setItem(KEY,x.json);toast('تم الاسترجاع... بيتعاد تحميل البرنامج');U=null;setTimeout(()=>location.reload(),700)}catch(e){toast('تعذّر الاسترجاع')}}
function snapHtml(){setTimeout(snapList,150);return `<div class="m">البرنامج بياخد نقطة استرجاع تلقائي كل نص ساعة (قبل أول تعديل)، وقبل الحذف والإلغاء والاستيراد، وبيحتفظ بآخر 12 نقطة. تقدر تاخد نقطة بإيدك أو ترجع لأي نقطة. النقاط محفوظة في متصفح الجهاز ده بس.</div><div class="row" style="justify-content:flex-start;gap:8px;margin:10px 0"><button type="button" class="btn s" onclick="snapMan()">📌 نقطة استرجاع الآن</button></div><div class="lrl" id="snapl"><div class="m">جاري التحميل...</div></div>`}
[['cancelPinv','إلغاء فاتورة شراء'],['cancelSale','إلغاء فاتورة بيع'],['delCashE','حذف حركة خزنة'],['delItems','حذف أصناف'],['delRow','حذف صف'],['importData','استيراد بيانات'],['resetDemo','مسح بيانات التجربة'],['delQuote','حذف عرض سعر'],['wipeData','مسح كل بيانات البرنامج'],['delCount','إلغاء جرد']].forEach(x=>{const f=window[x[0]];if(typeof f!='function')return;window[x[0]]=function(){snapNow('قبل: '+x[1]);return f.apply(this,arguments)}});
