async function scanBarcode(){try{const C=window.Capacitor,BS=(C&&C.isNativePlatform&&C.isNativePlatform())?((C.Plugins&&C.Plugins.BarcodeScanner)||C.registerPlugin('BarcodeScanner')):null;
if(BS){try{const a=await BS.isGoogleBarcodeScannerModuleAvailable();if(a&&a.available===false){toast('بيتجهّز الماسح لأول مرة... استنى ثواني');await BS.installGoogleBarcodeScannerModule()}}catch(e){}
const r=await BS.scan(),b=r&&r.barcodes&&r.barcodes[0];return b?String(b.rawValue||b.displayValue||''):null}}catch(e){if(String(e&&(e.message||e)).toLowerCase().includes('cancel'))return null;toast('تعذّر فتح الكاميرا: '+(e&&e.message||e));return null}
return webScan()}
function webScan(){return new Promise(async res=>{if(!('BarcodeDetector' in window)||!navigator.mediaDevices){toast('قراءة الباركود بالكاميرا مش متاحة هنا — استخدم تطبيق الموبايل');return res(null)}
let st=null,done=false;const fin=v=>{if(done)return;done=true;try{st&&st.getTracks().forEach(t=>t.stop())}catch(e){}$('ov2').className='';res(v)};
$('box2').innerHTML='<h2>📷 امسح الباركود</h2><video id="scv" playsinline muted style="width:100%;border-radius:12px;background:#000"></video><div class="row" style="margin-top:10px"><button type="button" class="btn g" id="scx">إلغاء</button></div>';$('ov2').className='on';$('scx').onclick=()=>fin(null);
try{st=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const v=$('scv');v.srcObject=st;await v.play();const det=new BarcodeDetector({formats:['ean_13','ean_8','code_128','code_39','upc_a','upc_e','itf','qr_code']});const tick=async()=>{if(done)return;try{const r=await det.detect(v);if(r&&r[0]){try{beep(1)}catch(e){}return fin(r[0].rawValue)}}catch(e){}setTimeout(tick,250)};tick()}catch(e){toast('تعذّر فتح الكاميرا: '+(e&&e.message||e));fin(null)}})}
