window.__snapUnlock=async pw=>{const k0=await crypto.subtle.importKey('raw',new TextEncoder().encode(pw),'PBKDF2',false,['deriveKey']),key=await crypto.subtle.deriveKey({name:'PBKDF2',salt:b(E.s),iterations:200000,hash:'SHA-256'},k0,{name:'AES-GCM',length:256},false,['decrypt']),raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:b(E.i)},key,b(E.c)),ds=new DecompressionStream('gzip'),w=ds.writable.getWriter();w.write(new Uint8Array(raw));w.close();const txt=new TextDecoder().decode(await new Response(ds.readable).arrayBuffer());try{sessionStorage.setItem('__snapd',txt);sessionStorage.setItem('__snapt',String(E.t))}catch(e){}return{txt:txt,t:E.t}};
