/* ===== حسابات الفلوس: صافي الكمية والربح والمرتجعات ===== */
const netQ=l=>l.q-(l.r||0);
const saleProfit=s=>s.tot-s.lines.reduce((b,l)=>b+l.c*netQ(l),0);
const lineRevF=s=>{const base=s.lines.filter(l=>!l.carry&&l.iid!=-1).reduce((a,l)=>a+l.p*netQ(l),0);return base>0?stv(s)/base:1};
/* ===== ربح الأقساط موزّع شهرياً: ربح الفاتورة بالكامل مقسوم على عدد الأشهر، كل حصة على تاريخ استحقاق قسطها ===== */
function instLineShares(s){const f=lineRevF(s);return s.lines.filter(l=>!l.carry&&l.iid!=-1).map(l=>({l,p:l.p*netQ(l)*f-l.c*netQ(l)}))}
function instMonths(s){if(s.type!='inst'||!s.months)return[];const per=saleProfit(s)/s.months,out=[];for(let k=1;k<=s.months;k++)out.push({k,due:due(s,k),profit:per});return out}
function instProfitInRange(s,f,t){return instMonths(s).filter(x=>x.due>=f&&x.due<=t).reduce((a,x)=>a+x.profit,0)}
/* أرباح الفترة: نقدي (حسب تاريخ البيع) + أقساط (حسب تاريخ استحقاق كل قسط) */
function periodProfit(f,t){const instAll=D.sales.filter(s=>s.type=='inst'&&!s.legacy);
const byCustC={},byProdC={},byCat={};let cashP=0;
D.sales.filter(s=>s.type=='cash'&&!s.legacy&&s.date>=f&&s.date<=t).forEach(s=>{const rf=lineRevF(s);s.lines.filter(l=>!l.carry&&l.iid!=-1).forEach(l=>{const rv=l.p*netQ(l)*rf,cs=l.c*netQ(l),pf=rv-cs;cashP+=pf;byCustC[s.cust]=(byCustC[s.cust]||0)+pf;const nm=item(l.iid)?item(l.iid).s:'-';byProdC[nm]=(byProdC[nm]||0)+pf;const cn=cat(item(l.iid).cat).n,x=byCat[cn]||(byCat[cn]={s:0,c:0});x.s+=rv;x.c+=cs})});
const byCustI={},byProdI={},instDetail=[];let instP=0,instMarkupP=0;
instAll.forEach(s=>{const rf=lineRevF(s),lines=s.lines.filter(l=>!l.carry&&l.iid!=-1),net=(s.sub!=null?s.sub:s.tot)-(s.disc||0),markup=Math.max(0,s.tot-net),markupPerMo=markup/s.months;
for(let k=1;k<=s.months;k++){const d=due(s,k);if(d<f||d>t)continue;let moAmt=0;lines.forEach(l=>{const rv=(l.p*netQ(l)*rf)/s.months,cs=(l.c*netQ(l))/s.months,pf=rv-cs;moAmt+=pf;instP+=pf;byCustI[s.cust]=(byCustI[s.cust]||0)+pf;const nm=item(l.iid)?item(l.iid).s:'-';byProdI[nm]=(byProdI[nm]||0)+pf;const cn=cat(item(l.iid).cat).n,x=byCat[cn]||(byCat[cn]={s:0,c:0});x.s+=rv;x.c+=cs});instMarkupP+=markupPerMo;instDetail.push({s,k,d,amt:moAmt})}});
return{cashP,instP,instProdP:instP-instMarkupP,instMarkupP,tp:cashP+instP,byCustC,byProdC,byCustI,byProdI,byCat,instDetail}}
function effP(s,l){const g=s.gn||0;return(g>0&&s.disc>0)?Math.round(l.p*(1-s.disc/g)*100)/100:l.p}
function retCalc(s,cr){cr=Math.round((cr||0)*100)/100;let nt,nd=s.down,nn1=null;
const gl=s.lines.filter(l=>!l.carry&&l.iid!=-1).reduce((a,l)=>a+l.p*netQ(l),0);
if(s.type=='inst'&&s.rate!=null&&gl>0){const cy=+s.carry||0,r=s.er!=null?s.er:(s.rate||0),nn=s.nn!=null?s.nn:Math.max(0,gl-(s.disc||0)),f=(n,d)=>{const dn=Math.min(d,n),dc=Math.min(Math.max(0,d-n),cy);return d+(n-dn)*(1+r/100)+(cy-dc)},ok=Math.abs(f(nn,Math.min(s.down,nn+cy))-s.tot)<=1;
nn1=Math.max(0,nn-cr);nd=Math.min(s.down,nn1+cy);nt=ok?Math.round(f(nn1,nd)*100)/100:Math.round(s.tot*((nn1+cy)/((nn+cy)||1))*100)/100;if(!ok)nd=Math.min(s.down,nt)}
else nt=Math.max(0,Math.round((s.tot-cr)*100)/100);
const refund=Math.max(0,Math.round((s.paid-nt)*100)/100);
return{cr:cr,nt:nt,nd:nd,nn1:nn1,refund:refund,d0:Math.max(0,Math.round((s.tot-s.paid)*100)/100),d1:Math.max(0,Math.round((nt-(s.paid-refund))*100)/100)}}
function retSum(){const el=$('retsum');if(!el||!RT.sid)return;const s=D.sales.find(x=>x.id==RT.sid),c=retCalc(s,(RT.p||0)*(RT.q||0));el.innerHTML='قيمة المرتجع: <b>'+m(c.cr)+'</b><br>المتبقي على العميل: '+m(c.d0)+' ← <b>'+m(c.d1)+'</b><br>اللي هيتردّ للعميل نقداً من الخزنة: <b style="color:var('+(c.refund>0?'--bad':'--ok')+')">'+m(c.refund)+'</b>'+((c.d0>0&&c.refund==0)?'<div class="m">العميل لسه عليه فلوس، فالمرتجع بيتخصم من مديونيته ومفيش فلوس بتخرج من الخزنة.</div>':'')+((c.d0>0&&c.refund>0)?'<div class="m">بيتردّ بس اللي العميل دفعه فعلاً زيادة عن قيمة الفاتورة بعد المرتجع.</div>':'')}
