function appActivationView(bad){
  $('app').innerHTML='<main style="max-width:390px;margin:12vh auto 0;padding:18px;box-sizing:border-box"><div class="k" style="text-align:center;padding:24px 18px"><div style="font-size:48px;margin-bottom:8px">🔐</div><h2 style="margin:4px 0 10px">تفعيل تطبيق معرض الشباسي</h2><div class="m" style="line-height:1.9;margin-bottom:16px">اكتب كلمة سر التفعيل للمتابعة. كلمة السر دي مختلفة عن كلمة سر ملف البيانات المشفّر.</div><label for="activationPassword" style="text-align:right">كلمة سر التفعيل</label><input id="activationPassword" type="password" autocomplete="off" style="height:48px;font-size:18px;text-align:center;direction:ltr" onkeydown="if(event.key===&quot;Enter&quot;)appActivationGo()">'+(bad?'<div style="color:var(--bad);margin-top:8px;font-weight:700">كلمة سر التفعيل غير صحيحة</div>':'')+'<button type="button" class="btn" style="width:100%;margin-top:16px" onclick="appActivationGo()">تفعيل وفتح التطبيق</button></div></main>';
  setTimeout(()=>{const e=$('activationPassword');if(e)e.focus()},80);
}
function appActivationGo(){const e=$('activationPassword');if(!e)return;if(e.value!==APP_ACTIVATION_PASSWORD){appActivationView(true);return}try{localStorage.setItem('acc_activation_ok','1')}catch(err){}location.reload()}
if(MOB&&!localStorage.getItem('acc_activation_ok'))appActivationView(false);
else if(MOB&&MOB_EMPTY)mobImportV();else if(MOB){try{MOB_ENV=JSON.parse(localStorage.getItem('acc_mob_env')||'null')}catch(e){MOB_ENV=null}if(MOB_ENV)mobAskPw(false);else mobImportV()}else loginV();
if(window.__MOBILE__)mobInitNative();
function mobAutoLogin(){U=(D.u||[]).find(x=>x.role=='a')||(D.u||[])[0]||{n:'عرض',un:'',role:'a'};tab='dash';applySet();shell()}
function mobLogout(){if(!confirm('هيتقفل التطبيق وهتدخل كود التشفير تاني لفتح نفس الملف المحفوظ. متابعة؟'))return;mobAutoLock()}
